// Inheritance trap: each combination needs a class.
// Composition: behaviors combine freely.
public class OrderPricer
{
    private readonly IDiscountPolicy discounts;
    private readonly ITaxPolicy taxes;
    public OrderPricer(IDiscountPolicy discounts, ITaxPolicy taxes)
    { this.discounts = discounts; this.taxes = taxes; }
    public decimal Price(Order order)
    { return taxes.Apply(discounts.Apply(order.Subtotal)); }
}

