public class LoggingNotifier : INotifier
{
    private readonly INotifier inner;
    private readonly ILogger<LoggingNotifier> logger;
    public LoggingNotifier(INotifier inner, ILogger<LoggingNotifier> logger)
    { this.inner = inner; this.logger = logger; }
    public async Task SendAsync(string message, CancellationToken ct)
    {
        logger.LogInformation("Sending notification.");
        await inner.SendAsync(message, ct);
        logger.LogInformation("Notification sent.");
    }
}

